import React, { useState } from "react";

const AddIncome = ({ onAdd }) => {
  const [amount, setAmount] = useState("");
  const [category, setCategory] = useState("");

  const handleSubmit = (e) => {
    e.preventDefault();
    if (!amount || !category) return;
    onAdd({ type: "income", amount: +amount, category });
    setAmount("");
    setCategory("");
  };

  return (
    <form onSubmit={handleSubmit} style={{ marginTop: "20px" }}>
      <h3>Add Income</h3>
      <input type="number" value={amount} onChange={e => setAmount(e.target.value)} placeholder="Amount" style={{ marginRight: "10px" }} />
      <input type="text" value={category} onChange={e => setCategory(e.target.value)} placeholder="Category" />
      <button type="submit" style={{ marginLeft: "10px" }}>Add</button>
    </form>
  );
};

export default AddIncome;
